import{c as l,Q as a,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const p=JSON.parse('{"title":"HCCL Tiling构造函数","description":"","frontmatter":{},"headers":[{"level":1,"title":"HCCL Tiling构造函数","slug":"hccl-tiling构造函数"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Tiling侧接口/HCCL-Tiling构造函数.md","filePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Tiling侧接口/HCCL-Tiling构造函数.md"}'),C={name:"api/SIMD-API/高阶API/HCCL通信类/HCCL-Tiling侧接口/HCCL-Tiling构造函数.md"};function i(s,t,_,o,d,A){return a(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="hccl-tiling构造函数" tabindex="-1">HCCL Tiling构造函数 <a class="header-anchor" href="#hccl-tiling构造函数" aria-label="Permalink to &quot;HCCL Tiling构造函数&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>用于创建一个Mc2CcTilingConfig对象。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Mc2CcTilingConfig(const std::string &amp;groupName, uint32_t opType, const std::string &amp;algConfig, uint32_t reduceType = 0, uint8_t dstDataType = 0, uint8_t srcDataType = 0, uint8_t commEngine = 0)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>groupName</td><td>输入</td><td>当前通信任务所在的通信域。string类型，支持的最大长度为128字节。</td></tr><tr><td>opType</td><td>输入</td><td>表示通信任务类型。uint32_t类型。HCCL API提供HcclCMDType枚举定义作为该参数的取值，具体支持的通信任务类型及取值请参考表2。</td></tr><tr><td>algConfig</td><td>输入</td><td>通信算法配置。string类型，支持的最大长度为128字节。 针对Ascend 950PR/Ascend 950DT，该参数为预留字段，配置后不生效，默认仅支持FullMesh算法。FullMesh算法即NPU之间的全连接，任意两个NPU之间可以直接进行数据收发。 针对Atlas A3 训练系列产品/Atlas A3 推理系列产品，当前支持的取值为： &quot;AllReduce=level0:doublering&quot;：AllReduce通信任务。&quot;AllGather=level0:doublering&quot;：AllGather通信任务。&quot;ReduceScatter=level0:doublering&quot;：ReduceScatter通信任务。&quot;AlltoAll=level0:fullmesh;level1:pairwise&quot;：AlltoAllV和AlltoAll通信任务。&quot;BatchWrite=level0:fullmesh&quot;：BatchWrite通信任务。 针对Atlas A2 训练系列产品/Atlas A2 推理系列产品，该参数为预留字段，配置后不生效，默认仅支持FullMesh算法。FullMesh算法即NPU之间的全连接，任意两个NPU之间可以直接进行数据收发。</td></tr><tr><td>reduceType</td><td>输入</td><td>归约操作类型，仅对有归约操作的通信任务生效。uint32_t类型，取值详见表2。</td></tr><tr><td>dstDataType</td><td>输入</td><td>通信任务中输出数据的数据类型。uint8_t类型，该参数的取值范围请参考表1。 Ascend 950PR/Ascend 950DT，不同通信任务支持的输出数据类型不同，具体为： 对于AllReduce、AllGather、AllToAll、AllToAllV、AllToAllVWrite通信任务：输出的数据类型必须与输入的数据类型一致。各通信任务支持的输入数据类型请参考srcDataType。对于ReduceScatter通信任务，当输入的数据类型为int16_t、int32_t、half、float、bfloat16_t时，输出的数据类型必须与其一致；当输入的数据类型为int8_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t时，输出的数据类型必须为half、bfloat16_t、float三者之一。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，该参数暂不支持，配置后不生效。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，该参数暂不支持，配置后不生效。</td></tr><tr><td>srcDataType</td><td>输入</td><td>通信任务中输入数据的数据类型。uint8_t类型，该参数的取值范围请参考表1。 Ascend 950PR/Ascend 950DT，不同通信任务支持的输入数据类型如下： AllReduce通信任务：支持的输入类型为int16_t、half、bfloat16_t、int32_t、float。AllGather、AllToAll、AllToAllV、AllToAllVWrite通信任务：支持的输入类型为int8_t、uint8_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、int64_t、double。ReduceScatter通信任务：支持的输入类型为int8_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、int16_t、half、bfloat16_t、int32_t、float。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，该参数暂不支持，配置后不生效。 针对Atlas A2 训练系列产品/Atlas A2 推理系列产品，该参数暂不支持，配置后不生效。</td></tr><tr><td>commEngine</td><td>输入</td><td>通信引擎。uint8_t类型，该参数的取值范围请参考：《HCCL集合通信库接口》&gt;HCCL API (C)&gt;数据类型&gt;HcclCommConfig中的hcclOpExpansionMode参数取值说明。</td></tr></tbody></table><p><strong>表 2</strong> HcclCMDType参数说明</p><table tabindex="0"><thead><tr><th>数据类型</th><th>说明</th></tr></thead><tbody><tr><td>HcclCMDType</td><td>通信任务类型。 针对Ascend 950PR/Ascend 950DT，当前支持的通信任务类型为HCCL_CMD_ALLREDUCE、HCCL_CMD_ALLGATHER、HCCL_CMD_REDUCE_SCATTER、HCCL_CMD_ALLTOALL、HCCL_CMD_ALLTOALLV、HCCL_CMD_HALF_ALLTOALLV。 针对Atlas A3 训练系列产品/Atlas A3 推理系列产品，当前支持的通信任务类型为HCCL_CMD_ALLREDUCE、HCCL_CMD_ALLGATHER、HCCL_CMD_REDUCE_SCATTER、HCCL_CMD_ALLTOALL、HCCL_CMD_ALLTOALLV、HCCL_CMD_BATCH_WRITE。 针对Atlas A2 训练系列产品/Atlas A2 推理系列产品，当前支持的通信任务类型为HCCL_CMD_ALLREDUCE、HCCL_CMD_ALLGATHER、HCCL_CMD_REDUCE_SCATTER、HCCL_CMD_ALLTOALL、HCCL_CMD_BATCH_WRITE。 &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen11611163816318&quot;&gt;enum class HcclCMDType { HCCL_CMD_INVALID = 0, HCCL_CMD_BROADCAST = 1, HCCL_CMD_ALLREDUCE, HCCL_CMD_REDUCE, HCCL_CMD_SEND, HCCL_CMD_RECEIVE, HCCL_CMD_ALLGATHER, HCCL_CMD_REDUCE_SCATTER, HCCL_CMD_ALLTOALLV, HCCL_CMD_ALLTOALLVC, HCCL_CMD_ALLTOALL, HCCL_CMD_GATHER, HCCL_CMD_SCATTER, HCCL_CMD_BATCH_SEND_RECV, HCCL_CMD_BATCH_PUT, HCCL_CMD_BATCH_GET, HCCL_CMD_ALLGATHER_V, HCCL_CMD_REDUCE_SCATTER_V, HCCL_CMD_BATCH_WRITE, HCCL_CMD_HALF_ALLTOALLV = 20, HCCL_CMD_ALL };&lt;/pre&gt;</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const char *groupName = &quot;testGroup&quot;;</span></span>
<span class="line"><span>uint32_t opType = HCCL_CMD_REDUCE_SCATTER;</span></span>
<span class="line"><span>std::string algConfig = &quot;ReduceScatter=level0:fullmesh&quot;;</span></span>
<span class="line"><span>uint32_t reduceType = HCCL_REDUCE_SUM;</span></span>
<span class="line"><span>uint8_t dstDataType = HCCL_DATA_TYPE_FP16;</span></span>
<span class="line"><span>uint8_t srcDataType = HCCL_DATA_TYPE_FP16;</span></span>
<span class="line"><span>uint8_t commEngine = 0;</span></span>
<span class="line"><span>AscendC::Mc2CcTilingConfig mc2CcTilingConfig(groupName, opType, algConfig, reduceType, dstDataType, srcDataType, commEngine); // 构造函数</span></span>
<span class="line"><span>mc2CcTilingConfig.GetTiling(tiling-&gt;mc2InitTiling);  // tiling为算子组装的TilingData结构体</span></span>
<span class="line"><span>mc2CcTilingConfig.GetTiling(tiling-&gt;reduceScatterTiling);</span></span></code></pre></div>`,16)])])}const r=l(C,[["render",i]]);export{p as __pageData,r as default};
